import React, { useEffect, useState } from 'react';
import { Phone, Mail, MapPin, Clock } from 'lucide-react';
import { Button } from '../components/ui/button';
import { Card, CardContent } from '../components/ui/card';
import { Input } from '../components/ui/input';
import { Textarea } from '../components/ui/textarea';
import { toast } from 'sonner';
import { SITE, smsLink } from '@/data/site';

const Contact = () => {
  const [formData, setFormData] = useState({ name: '', phone: '', service: '', message: '' });

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const handleInputChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;
      const response = await fetch(`${BACKEND_URL}/api/quote-request`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });
      if (response.ok) {
        toast.success("Thanks. We'll be in touch shortly.");
        const serviceMap = {
          kitchen: 'a kitchen renovation',
          bathroom: 'a bathroom renovation',
          basement: 'a basement build',
          tile: 'tile or flooring work',
          multiple: 'a full renovation',
        };
        const serviceName = serviceMap[formData.service] || 'a renovation project';
        let sms = `Hi JAG, this is ${formData.name}. I'm looking to get a quote for ${serviceName}.`;
        if (formData.message?.trim()) sms += ` ${formData.message}`;
        sms += ` You can reach me at ${formData.phone}.`;
        window.open(`sms:${SITE.phone}?body=${encodeURIComponent(sms)}`, '_blank');
        setFormData({ name: '', phone: '', service: '', message: '' });
      } else {
        toast.error('Something went wrong. Text or call us directly.');
      }
    } catch (err) {
      toast.error('Something went wrong. Text or call us directly.');
    }
  };

  return (
    <div>
      {/* Page header */}
      <section className="pt-32 pb-12 px-4 sm:px-6 lg:px-8 bg-[#FAF6EF] border-b border-stone-200">
        <div className="max-w-5xl mx-auto">
          <p className="text-[#8B6F47] text-xs font-semibold uppercase tracking-[0.3em] mb-3">Get in touch</p>
          <h1 className="text-3xl sm:text-5xl font-bold text-stone-900 mb-3 tracking-tight">Start a project.</h1>
          <p className="text-base sm:text-lg text-stone-600 font-light max-w-2xl">
            Tell us a little about the space and what you have in mind. Most quotes go out within five business days of the site visit.
          </p>
        </div>
      </section>

      <section className="py-16 sm:py-20 px-4 sm:px-6 lg:px-8 bg-white">
        <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-5 gap-10">
          {/* Info */}
          <div className="lg:col-span-2 space-y-5">
            <h2 className="text-2xl font-bold text-stone-900 mb-2">Reach us</h2>
            <p className="text-stone-600 font-light leading-relaxed">
              Texting is the fastest way to get a reply during the day. Calls go to voicemail when we&apos;re on a job site, but we&apos;ll get back same day.
            </p>

            {[
              { icon: Phone, title: 'Phone', body: <a href={`tel:${SITE.phone}`} className="text-stone-900 hover:text-[#8B6F47] text-lg font-medium">{SITE.phone}</a> },
              { icon: Mail, title: 'Email', body: <a href={`mailto:${SITE.email}`} className="text-stone-900 hover:text-[#8B6F47] font-medium break-all">{SITE.email}</a> },
              { icon: Clock, title: 'Hours', body: <p className="text-stone-600">{SITE.hours}</p> },
              { icon: MapPin, title: 'Service Area', body: <p className="text-stone-600">Greater Toronto Area</p> },
            ].map(({ icon: Icon, title, body }) => (
              <div key={title} className="flex items-start gap-4 p-5 border border-stone-200">
                <div className="w-10 h-10 bg-[#FAF6EF] flex items-center justify-center flex-shrink-0">
                  <Icon className="text-[#8B6F47]" size={18} />
                </div>
                <div>
                  <p className="text-[10px] font-semibold uppercase tracking-wider text-stone-500 mb-1">{title}</p>
                  {body}
                </div>
              </div>
            ))}

            <a href={smsLink()} className="block">
              <Button size="lg" className="w-full bg-stone-900 hover:bg-stone-800 text-white font-semibold uppercase tracking-wider text-sm py-6">
                Text Us Now
              </Button>
            </a>
          </div>

          {/* Form */}
          <div className="lg:col-span-3">
            <Card className="border border-stone-200 shadow-none bg-white">
              <CardContent className="p-7 sm:p-10">
                <h2 className="text-2xl font-bold text-stone-900 mb-2">Project enquiry</h2>
                <p className="text-stone-600 mb-8 font-light">Fill this out and we&apos;ll be in touch. Photos help &mdash; if you have any, text them through after.</p>
                <form onSubmit={handleSubmit} className="space-y-5">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    <div>
                      <label htmlFor="name" className="block text-xs font-semibold uppercase tracking-wider text-stone-700 mb-2">Name *</label>
                      <Input id="name" name="name" value={formData.name} onChange={handleInputChange} required className="border-stone-300 focus:border-stone-900 focus:ring-stone-900 h-12 rounded-none" placeholder="Your name" />
                    </div>
                    <div>
                      <label htmlFor="phone" className="block text-xs font-semibold uppercase tracking-wider text-stone-700 mb-2">Phone *</label>
                      <Input id="phone" name="phone" type="tel" value={formData.phone} onChange={handleInputChange} required className="border-stone-300 focus:border-stone-900 focus:ring-stone-900 h-12 rounded-none" placeholder="Your phone number" />
                    </div>
                  </div>

                  <div>
                    <label htmlFor="service" className="block text-xs font-semibold uppercase tracking-wider text-stone-700 mb-2">Project type</label>
                    <select id="service" name="service" value={formData.service} onChange={handleInputChange} className="w-full border border-stone-300 rounded-none px-4 py-3 focus:border-stone-900 focus:ring-1 focus:ring-stone-900 focus:outline-none h-12">
                      <option value="">Select project type</option>
                      <option value="kitchen">Kitchen Renovation</option>
                      <option value="bathroom">Bathroom Renovation</option>
                      <option value="basement">Basement Finishing</option>
                      <option value="tile">Tile &amp; Flooring</option>
                      <option value="multiple">Multiple / Full Renovation</option>
                    </select>
                  </div>

                  <div>
                    <label htmlFor="message" className="block text-xs font-semibold uppercase tracking-wider text-stone-700 mb-2">Project details</label>
                    <Textarea id="message" name="message" value={formData.message} onChange={handleInputChange} rows={6} className="border-stone-300 focus:border-stone-900 focus:ring-stone-900 resize-none rounded-none" placeholder="Address, rough scope, timeline, anything else we should know..." />
                  </div>

                  <Button type="submit" size="lg" className="w-full bg-stone-900 hover:bg-stone-800 text-white font-semibold uppercase tracking-wider text-sm py-6">
                    Send Enquiry
                  </Button>
                </form>
              </CardContent>
            </Card>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Contact;
