import React from 'react';
import { Star } from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Avatar, AvatarFallback, AvatarImage } from './ui/avatar';

const initialsOf = (name) =>
  name
    .split(' ')
    .map((n) => n[0])
    .slice(0, 2)
    .join('')
    .toUpperCase();

const ReviewCard = ({ review }) => {
  return (
    <Card className="border border-stone-200 shadow-sm h-full bg-white hover:shadow-lg transition-shadow duration-300">
      <CardContent className="p-7 flex flex-col h-full">
        <div className="flex items-center gap-3 mb-4">
          <Avatar className="h-12 w-12 ring-2 ring-stone-100">
            <AvatarImage src={review.avatar} alt={review.name} />
            <AvatarFallback className="bg-stone-100 text-stone-700 font-semibold">
              {initialsOf(review.name)}
            </AvatarFallback>
          </Avatar>
          <div className="min-w-0">
            <p className="font-semibold text-stone-900 leading-tight truncate">{review.name}</p>
            <p className="text-xs text-stone-500">{review.location}</p>
          </div>
        </div>
        <div className="flex items-center justify-between mb-3">
          <div className="flex gap-0.5">
            {Array.from({ length: review.rating }).map((_, i) => (
              <Star key={i} className="fill-[#8B6F47] text-[#8B6F47]" size={16} />
            ))}
          </div>
          {review.project && (
            <span className="text-[10px] font-semibold uppercase tracking-wider text-[#8B6F47] bg-[#FAF6EF] px-2 py-1 rounded">
              {review.project}
            </span>
          )}
        </div>
        <p className="text-stone-700 leading-relaxed flex-grow text-[15px]">
          “{review.text}”
        </p>
      </CardContent>
    </Card>
  );
};

export default ReviewCard;
