import React, { useEffect, useState } from 'react';
import { Link, NavLink, useLocation } from 'react-router-dom';
import { Menu, Phone } from 'lucide-react';
import { Button } from '../ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '../ui/dropdown-menu';
import { SITE, NAV_LINKS, smsLink } from '@/data/site';

const Logo = ({ solid }) => (
  <Link to="/" className="flex items-center group">
    <img
      src={SITE.logo}
      alt={SITE.name}
      className={`h-20 sm:h-24 w-auto object-contain transition-all duration-300 ${
        solid ? '' : 'brightness-0 invert'
      }`}
    />
  </Link>
);

const Header = () => {
  const location = useLocation();
  const isHome = location.pathname === '/';
  const [isScrolled, setIsScrolled] = useState(!isHome);

  useEffect(() => {
    if (!isHome) {
      setIsScrolled(true);
      return;
    }
    const handleScroll = () => setIsScrolled(window.scrollY > 10);
    handleScroll();
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [isHome]);

  const solid = isScrolled;

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        solid
          ? 'bg-white/95 backdrop-blur-xl border-b border-stone-200 shadow-sm'
          : 'bg-transparent'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-24">
          <Logo solid={solid} />

          <div className="flex items-center gap-1 sm:gap-2">
            <nav className="hidden lg:flex items-center gap-1 mr-1">
              {NAV_LINKS.map((link) => (
                <NavLink
                  key={link.to}
                  to={link.to}
                  end={link.to === '/'}
                  className={({ isActive }) =>
                    `px-3 py-2 text-sm font-medium uppercase tracking-wider transition-colors duration-200 ${
                      solid
                        ? isActive
                          ? 'text-stone-900 border-b-2 border-[#8B6F47]'
                          : 'text-stone-600 hover:text-stone-900'
                        : isActive
                        ? 'text-white border-b-2 border-[#D4B896]'
                        : 'text-white/85 hover:text-white'
                    }`
                  }
                >
                  {link.label}
                </NavLink>
              ))}
            </nav>

            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className={`lg:hidden transition-colors duration-300 ${
                    solid
                      ? 'text-stone-900 hover:bg-stone-100'
                      : 'text-white hover:bg-white/15'
                  }`}
                >
                  <Menu size={24} />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent
                align="end"
                className="w-56 bg-white border-stone-200"
              >
                {NAV_LINKS.map((link) => (
                  <DropdownMenuItem asChild key={link.to}>
                    <Link to={link.to} className="w-full cursor-pointer font-medium uppercase tracking-wider text-xs">
                      {link.label}
                    </Link>
                  </DropdownMenuItem>
                ))}
                <DropdownMenuItem asChild>
                  <a
                    href={`tel:${SITE.phone}`}
                    className="w-full cursor-pointer flex items-center gap-2 font-medium text-xs"
                  >
                    <Phone size={14} />
                    <span>{SITE.phone}</span>
                  </a>
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>

            <a href={smsLink()}>
              <Button
                className={`font-semibold uppercase tracking-wider text-xs px-5 py-2 transition-colors duration-300 ${
                  solid
                    ? 'bg-stone-900 hover:bg-stone-800 text-white'
                    : 'bg-white hover:bg-stone-100 text-stone-900'
                }`}
              >
                Get a Quote
              </Button>
            </a>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;
